struct AccountData {
    // Copilot uses only extraUsage for the monthly quota; these fields are not persisted.
    std::wstring copilotLogin;
    std::wstring copilotResetDate;
    double copilotRemaining = -1;
    bool copilotUnlimited = false;
    WindowUsage win5h;
    WindowUsage winWeek;
    WindowUsage fableWeek;
    WindowUsage extraUsage;
    WindowUsage antigravityThirdParty5h;
    WindowUsage antigravityThirdPartyWeek;
    // Bounded additional quotas, with no arc or alerts; not persisted.
    std::vector<std::pair<std::wstring, WindowUsage>> antigravityOtherQuotas;
    // Last fetch route, including failed attempts; not persisted.
    bool antigravityLocalRoute = false;
    std::vector<AdditionalMeter> additionalMeters;
    std::wstring plan;
    std::wstring extraLines;
    // Amounts behind the extra-usage slot, in dollars (Anthropic) or credits (OpenAI);
    // -1 when unknown. Left = limit - used. Used may go negative if a credits balance
    // exceeds the configured max.
    double extraUsedAmount = -1;
    double extraLimitAmount = -1;
    // OpenAI prepaid credits; balance is -1 when the API reports none or hides it.
    bool hasCredits = false;
    bool creditsUnlimited = false;
    double creditsBalance = -1;
    // Banked free resets (Claude "cedar_ember", Codex rate_limit_reset_credits); -1 if the API does
    // not report them. Expiry of the next one in Unix ms; 0 if it does not expire or is unknown.
    int resetCreditsAvailable = -1;
    ULONGLONG resetCreditsExpiresMs = 0;
    // When the Anthropic plan was read from /api/oauth/profile (reread every 6 h).
    ULONGLONG planFetchedMs = 0;
    // Next allowed attempt for the optional profile after a failure.
    ULONGLONG planRetryDeadlineMs = 0;
    // Anthropic: when the free resets (cedar_ember) were last read. The Claude Code cache does not
    // carry them, so they expire on their own (see kClaudeResetTicketsMaxAgeMs).
    ULONGLONG resetCreditsFetchedMs = 0;
    std::wstring error;
    ULONGLONG lastSuccessMs = 0;
    ULONGLONG retryDeadlineMs = 0;
    // Next scheduled query (poll or retry); the flyout uses it for the countdown.
    ULONGLONG nextAttemptMs = 0;
    bool stale = true;
    bool needsLogin = false;  // Sign-in required; left-click signs in instead of refreshing.
};

// Data for each quota (QuotaBarIndex) of an account.
static const WindowUsage& BarUsage(const AccountData& d, int bar) {
    switch (bar) {
        case kFiveHourBar: return d.win5h;
        case kWeeklyBar: return d.winWeek;
        case kFableWeeklyBar: return d.fableWeek;
        case kOtherBar: return d.antigravityThirdParty5h;
        case kOtherWeeklyBar: return d.antigravityThirdPartyWeek;
        default: return d.extraUsage;
    }
}

// Tile arcs: one per quota checked in the account editor (session, weekly and credits/extra usage).
// The layout depends on how many are checked (TileArcLayout).
enum TileArcIndex {
    kSessionArc,
    kWeeklyArc,
    kCreditsArc,
    kTileArcCount,
};

// Whether the quota (QuotaBarIndex) is checked as a tile arc. showBars[kFableWeeklyBar] only
// means Fable is fetched; its arc has its own flag and needs the Fable weekly row.
static bool ShowsTileArc(AccountConfig const& account, int bar) {
    if (bar == kFableWeeklyBar) {
        return account.provider == L"anthropic" && account.showFableWeekly &&
               account.showFableWeeklyArc;
    }
    return account.showBars[bar];
}

// Quotas that can be arcs, in tile order, for accounts that choose up to kMaxTileArcs of four.
static std::array<int, 4> PickedArcOrder(AccountConfig const& account) {
    if (account.provider == L"antigravity") {
        return {kFiveHourBar, kWeeklyBar, kOtherBar, kOtherWeeklyBar};
    }
    return {kFiveHourBar, kWeeklyBar, kFableWeeklyBar, kExtraUsageBar};
}

// Quota (QuotaBarIndex) drawn by each tile position, or -1. For other providers each position has
// its fixed quota; Antigravity, and Claude with its Fable weekly arc, spread the checked ones (up
// to three) in PickedArcOrder: with two, top and bottom; with three, left, right and bottom.
static std::array<int, kTileArcCount> TileArcBars(AccountConfig const& account) {
    std::array<int, kTileArcCount> bars{-1, -1, -1};
    if (account.provider != L"antigravity" && !ShowsTileArc(account, kFableWeeklyBar)) {
        if (account.showBars[kFiveHourBar]) bars[kSessionArc] = kFiveHourBar;
        if (account.showBars[kWeeklyBar]) bars[kWeeklyArc] = kWeeklyBar;
        if (account.showBars[kExtraUsageBar]) bars[kCreditsArc] = kExtraUsageBar;
        return bars;
    }
    std::vector<int> chosen;
    for (int bar : PickedArcOrder(account)) {
        if (ShowsTileArc(account, bar) && (int)chosen.size() < kMaxTileArcs) chosen.push_back(bar);
    }
    static constexpr int kTwo[] = {kSessionArc, kWeeklyArc};
    static constexpr int kThree[] = {kSessionArc, kCreditsArc, kWeeklyArc};
    for (size_t k = 0; k < chosen.size(); k++) {
        bars[chosen.size() == 3 ? kThree[k] : kTwo[k]] = chosen[k];
    }
    return bars;
}

// Span of an arc in degrees (0 = right, clockwise on screen). The fill advances from startDeg in
// the direction of sweepDeg; sweepDeg = 0 means the arc is not shown.
struct ArcSpec {
    double startDeg = 0;
    double sweepDeg = 0;
};

