// Account emails (or "@login" for GitHub), keyed by AccountIdentityHash. Learned from the
// provider's own sign-in data and kept in mod storage so the flyout has them after a restart.
static std::mutex g_accountEmailMutex;
static std::vector<std::pair<uint64_t, std::wstring>> g_accountEmails;
static std::vector<uint64_t> g_accountEmailProbed;
static bool g_accountEmailsLoaded = false;
static constexpr PCWSTR kAccountEmailsKey = L"accountEmails_v1";

static void LoadAccountEmailsLocked() {
    if (g_accountEmailsLoaded) return;
    g_accountEmailsLoaded = true;
    std::vector<wchar_t> buf(16384, 0);
    Wh_GetStringValue(kAccountEmailsKey, buf.data(), buf.size());
    std::wstring all(buf.data());
    size_t pos = 0;
    while (pos < all.size()) {
        size_t end = all.find(L'\n', pos);
        if (end == std::wstring::npos) end = all.size();
        std::wstring line = all.substr(pos, end - pos);
        pos = end + 1;
        size_t tab = line.find(L'\t');
        if (tab == std::wstring::npos || tab == 0 || tab + 1 >= line.size()) continue;
        uint64_t id = wcstoull(line.substr(0, tab).c_str(), nullptr, 16);
        if (id) g_accountEmails.emplace_back(id, line.substr(tab + 1));
    }
}

static std::wstring GetAccountEmail(uint64_t id) {
    std::lock_guard<std::mutex> lk(g_accountEmailMutex);
    LoadAccountEmailsLocked();
    for (auto const& entry : g_accountEmails) {
        if (entry.first == id) return entry.second;
    }
    return {};
}

static void SetAccountEmail(uint64_t id, std::wstring email) {
    while (!email.empty() && iswspace(email.back())) email.pop_back();
    while (!email.empty() && iswspace(email.front())) email.erase(0, 1);
    if (!id || email.empty() || email.size() > 254) return;
    for (wchar_t ch : email) {
        if (ch < 0x20 || ch == 0x7F) return;
    }
    std::lock_guard<std::mutex> lk(g_accountEmailMutex);
    LoadAccountEmailsLocked();
    bool found = false;
    for (auto& entry : g_accountEmails) {
        if (entry.first != id) continue;
        if (entry.second == email) return;
        entry.second = email;
        found = true;
    }
    if (!found) g_accountEmails.emplace_back(id, email);
    std::wstring all;
    for (auto const& entry : g_accountEmails) {
        wchar_t hex[20];
        swprintf_s(hex, L"%016llx", (unsigned long long)entry.first);
        all += hex;
        all += L'\t';
        all += entry.second;
        all += L'\n';
    }
    if (all.size() < 16000) Wh_SetStringValue(kAccountEmailsKey, all.c_str());
}

// True once per session for an account whose email is still unknown: allows one extra request
// (profile or userinfo) to learn it.
static bool ShouldProbeAccountEmail(uint64_t id) {
    if (!GetAccountEmail(id).empty()) return false;
    std::lock_guard<std::mutex> lk(g_accountEmailMutex);
    for (uint64_t probed : g_accountEmailProbed) {
        if (probed == id) return false;
    }
    g_accountEmailProbed.push_back(id);
    return true;
}

static std::wstring JsonEmailField(winrt::Windows::Data::Json::JsonObject const& obj) {
    if (!obj) return {};
    for (PCWSTR key : {L"email", L"email_address", L"emailAddress"}) {
        if (obj.HasKey(key) &&
            obj.GetNamedValue(key).ValueType() == winrt::Windows::Data::Json::JsonValueType::String) {
            std::wstring value(obj.GetNamedString(key).c_str());
            if (value.find(L'@') != std::wstring::npos) return value;
        }
    }
    return {};
}
