template<typename T>
struct OAuthSecretWiper {
    T& value;
    ~OAuthSecretWiper() { WipeBuffer(value); }
};

static std::string UrlEncode(const std::string& s) {
    static const char* kHex = "0123456789ABCDEF";
    std::string out;
    out.reserve(s.size());
    for (unsigned char c : s) {
        if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
            out += (char)c;
        } else {
            out += '%';
            out += kHex[c >> 4];
            out += kHex[c & 0xF];
        }
    }
    return out;
}

static std::string UrlDecode(const std::string& s) {
    auto hex = [](char h) -> int {
        if (h >= '0' && h <= '9') return h - '0';
        if (h >= 'a' && h <= 'f') return h - 'a' + 10;
        if (h >= 'A' && h <= 'F') return h - 'A' + 10;
        return -1;
    };
    std::string out;
    out.reserve(s.size());
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (c == '%' && i + 2 < s.size()) {
            int hi = hex(s[i + 1]), lo = hex(s[i + 2]);
            if (hi >= 0 && lo >= 0) {
                out += (char)((hi << 4) | lo);
                i += 2;
                continue;
            }
        }
        out += (c == '+') ? ' ' : c;
    }
    return out;
}

static std::wstring BuildAnthropicAuthorizeUrl(const std::string& challenge, const std::string& state) {
    std::string url = "https://claude.ai/oauth/authorize?code=true";
    url += "&client_id=" + UrlEncode(WideToUtf8(kAnthropicClientId));
    url += "&response_type=code";
    url += "&redirect_uri=" + UrlEncode(WideToUtf8(kAnthropicRedirect));
    url += "&scope=" + UrlEncode(WideToUtf8(kAnthropicScope));
    url += "&code_challenge=" + challenge;
    url += "&code_challenge_method=S256";
    url += "&state=" + state;
    return Utf8ToWide(url);
}

static std::wstring BuildOpenAiAuthorizeUrl(int port, const std::string& challenge,
                                            const std::string& state) {
    std::string redirect = "http://localhost:" + std::to_string(port) + "/auth/callback";
    std::string url = "https://auth.openai.com/oauth/authorize?response_type=code";
    url += "&client_id=" + UrlEncode(WideToUtf8(kOpenAiClientId));
    url += "&redirect_uri=" + UrlEncode(redirect);
    url += "&scope=" + UrlEncode(WideToUtf8(kOpenAiScope));
    url += "&code_challenge=" + challenge;
    url += "&code_challenge_method=S256";
    url += "&id_token_add_organizations=true";
    url += "&codex_cli_simplified_flow=true";
    url += "&originator=codex_cli_rs";
    url += "&state=" + state;
    return Utf8ToWide(url);
}

enum class TokenEndpointResult {
    Success,
    Rejected,
    TransientFailure,
};

static std::wstring ParseOAuthError(const std::string& body) {
    try {
        auto root = JsonObject::Parse(Utf8ToWide(body));
        std::wstring desc = GetStr(root, L"error_description");
        if (!desc.empty()) return desc;
        return GetStr(root, L"error");
    } catch (...) {
        return {};
    }
}

// Fills *tok from an OAuth token response (access/refresh/id_token), extracting the OpenAI
// ChatGPT-Account-Id and access-token expiry from JWT claims when present. Used for both the
// authorization-code exchange and refresh.
static bool ParseTokenResponse(const std::string& body, bool anthropic, StoredToken* tok,
                               std::wstring* err) {
    try {
        auto root = JsonObject::Parse(Utf8ToWide(body));
        std::wstring access = GetStr(root, L"access_token");
        std::wstring refresh = GetStr(root, L"refresh_token");
        if (access.empty()) {
            *err = Tr(Str::StatusNoAccessToken);
            return false;
        }
        tok->accessToken = access;
        if (!refresh.empty()) tok->refreshToken = refresh;

        tok->expiresMs = 0;
        double expiresIn = GetNum(root, L"expires_in", 0);
        if (expiresIn > 0) tok->expiresMs = NowUnixMs() + (ULONGLONG)(expiresIn * 1000);

        if (!anthropic) {
            std::wstring idToken = GetStr(root, L"id_token");
            if (auto claims = ParseJwtPayload(idToken.empty() ? access : idToken)) {
                if (auto authObj = GetObj(claims, L"https://api.openai.com/auth")) {
                    std::wstring acc = GetStr(authObj, L"chatgpt_account_id");
                    if (!acc.empty()) tok->accountId = acc;
                }
            }
            // OpenAI responses omit expires_in; derive expiry from the access-token JWT exp.
            if (tok->expiresMs == 0) {
                if (auto claims = ParseJwtPayload(access)) {
                    double exp = GetNum(claims, L"exp", 0);
                    if (exp > 0) tok->expiresMs = (ULONGLONG)(exp * 1000);
                }
            }
        }
        return true;
    } catch (...) {
        *err = Tr(Str::StatusInvalidTokenResponse);
        return false;
    }
}

static TokenEndpointResult PostTokenEndpoint(bool anthropic, const std::wstring& contentType,
                                              const std::string& body, StoredToken* tok,
                                              std::wstring* err, int* retryAfterSec = nullptr) {
    if (retryAfterSec) *retryAfterSec = 0;
    std::wstring headers = L"Content-Type: " + contentType + L"\r\nAccept: application/json\r\n";
    PCWSTR host = anthropic ? kAnthropicTokenHost : kOpenAiTokenHost;
    PCWSTR path = anthropic ? kAnthropicTokenPath : kOpenAiTokenPath;
    HttpResult r = HttpRequest(L"POST", host, path, kOAuthUserAgent, headers, body);
    if (!r.ok) {
        *err = Tr(Str::StatusNetworkError);
        return TokenEndpointResult::TransientFailure;
    }
    if (r.status < 200 || r.status >= 300) {
        if (retryAfterSec) *retryAfterSec = r.retryAfterSec;
        std::wstring detail = ParseOAuthError(r.body);
        *err = detail.empty() ? TrFormat(Str::StatusHttp, {std::to_wstring(r.status)}) : detail;
        bool rejected = r.status >= 400 && r.status < 500 && r.status != 408 &&
                        r.status != 429;
        return rejected ? TokenEndpointResult::Rejected
                        : TokenEndpointResult::TransientFailure;
    }
    return ParseTokenResponse(r.body, anthropic, tok, err)
               ? TokenEndpointResult::Success
               : TokenEndpointResult::TransientFailure;
}

// Only exchanges or renews the mod's own credentials; never receives a borrowed refresh token.
static TokenEndpointResult PostAntigravityTokenEndpoint(const std::string& formBody,
                                                       StoredToken* token, std::wstring* error,
                                                       int* retryAfterSec = nullptr) {
    if (retryAfterSec) *retryAfterSec = 0;
    HttpResult result = HttpRequest(L"POST", L"oauth2.googleapis.com", L"/token", kOAuthUserAgent,
        L"Content-Type: application/x-www-form-urlencoded\r\nAccept: application/json\r\n", formBody,
        true);
    OAuthSecretWiper bodyWiper{result.body};
    if (!result.ok) {
        *error = Tr(Str::StatusNetworkError);
        WipeBuffer(result.body);
        return TokenEndpointResult::TransientFailure;
    }
    if (result.status < 200 || result.status >= 300) {
        if (retryAfterSec) *retryAfterSec = result.retryAfterSec;
        // The remote body is not included: it could repeat data from the OAuth exchange.
        *error = TrFormat(Str::StatusHttp, {std::to_wstring(result.status)});
        WipeBuffer(result.body);
        return result.status >= 400 && result.status < 500 && result.status != 408 && result.status != 429
            ? TokenEndpointResult::Rejected : TokenEndpointResult::TransientFailure;
    }
    bool parsed = ParseTokenResponse(result.body, false, token, error);
    WipeBuffer(result.body);
    return parsed ? TokenEndpointResult::Success : TokenEndpointResult::TransientFailure;
}

// Tokens of the mod's own Google sign-ins that were signed out or deleted, waiting for the fetch
// thread to revoke them at Google. Borrowed sign-ins are never queued.
static std::mutex g_googleRevocationMutex;
static std::vector<std::string> g_pendingGoogleRevocations;

// Reads the token to revoke before the caller deletes the stored sign-in (refresh token preferred:
// revoking it also ends its access tokens).
static std::string GoogleRevocationToken(uint64_t identity) {
    StoredToken token;
    if (!LoadStoredToken(identity, &token)) return {};
    std::string value = WideToUtf8(token.refreshToken.empty() ? token.accessToken : token.refreshToken);
    WipeBuffer(token.accessToken);
    WipeBuffer(token.refreshToken);
    return value;
}

static void QueueGoogleRevocation(std::string token) {
    if (token.empty()) return;
    std::lock_guard<std::mutex> lock(g_googleRevocationMutex);
    if (g_unloading) {
        WipeBuffer(token);
        return;
    }
    g_pendingGoogleRevocations.push_back(std::move(token));
}

static void WipePendingGoogleRevocations() {
    std::lock_guard<std::mutex> lock(g_googleRevocationMutex);
    for (auto& token : g_pendingGoogleRevocations) WipeBuffer(token);
    g_pendingGoogleRevocations.clear();
}

// Fetch thread only. The sign-in is already deleted from this PC, so a failed revocation is only
// logged; the user can still remove the app's access in their Google account.
static void RevokePendingGoogleTokens() {
    std::vector<std::string> tokens;
    {
        std::lock_guard<std::mutex> lock(g_googleRevocationMutex);
        tokens.swap(g_pendingGoogleRevocations);
    }
    for (auto& token : tokens) {
        if (!g_unloading) {
            std::string body = "token=" + UrlEncode(token);
            HttpResult result = HttpRequest(L"POST", L"oauth2.googleapis.com", L"/revoke", kOAuthUserAgent,
                L"Content-Type: application/x-www-form-urlencoded\r\n", body, true);
            WipeBuffer(body);
            WipeBuffer(result.body);
            Wh_Log(L"Google sign-in revocation %s (HTTP %d)",
                   result.ok && result.status == 200 ? L"succeeded" : L"failed", result.status);
        }
        WipeBuffer(token);
    }
}

// The project is obtained for the same session; a project of another user is never made up.
static void ResolveAntigravityProject(StoredToken* token) {
    if (g_unloading || !token->accountId.empty()) return;
    std::wstring headers = L"Authorization: Bearer " + token->accessToken +
        L"\r\nContent-Type: application/json\r\nAccept: application/json\r\n";
    OAuthSecretWiper headerWiper{headers};
    HttpResult result = HttpRequest(L"POST", L"cloudcode-pa.googleapis.com", L"/v1internal:loadCodeAssist",
        kAntigravityUserAgent, headers,
        R"({"metadata":{"ideType":"ANTIGRAVITY","platform":"WINDOWS_AMD64","pluginType":"GEMINI"}})",
        true);
    WipeBuffer(headers);
    if (result.ok && result.status >= 200 && result.status < 300) {
        try {
            auto root = JsonObject::Parse(Utf8ToWide(result.body));
            token->accountId = GetStr(root, L"cloudaicompanionProject");
            if (token->accountId.empty()) token->accountId = GetStr(GetObj(root, L"cloudaicompanionProject"), L"id");
        } catch (...) {}
    }
}

// grant_type=refresh_token. Anthropic sends JSON; OpenAI sends JSON too (its auth-code
// exchange is the form-encoded one). Rotated refresh tokens come back in the response.
static TokenEndpointResult RefreshToken(const std::wstring& provider, StoredToken* tok,
                                        std::wstring* err, int* retryAfterSec) {
    if (retryAfterSec) *retryAfterSec = 0;
    if (tok->refreshToken.empty()) {
        *err = Tr(Str::StatusNoRefreshToken);
        return TokenEndpointResult::Rejected;
    }
    if (provider == L"antigravity") {
        std::string formBody = "grant_type=refresh_token&refresh_token=" + UrlEncode(WideToUtf8(tok->refreshToken)) +
            "&client_id=" + UrlEncode(WideToUtf8(kAntigravityClientId)) +
            "&client_secret=" + UrlEncode(WideToUtf8(kAntigravityClientSecret));
        OAuthSecretWiper formWiper{formBody};
        auto result = PostAntigravityTokenEndpoint(formBody, tok, err, retryAfterSec);
        WipeBuffer(formBody);
        return result;
    }
    bool anthropic = provider == L"anthropic";
    std::string body;
    try {
        JsonObject obj;
        obj.SetNamedValue(L"grant_type", JsonValue::CreateStringValue(L"refresh_token"));
        obj.SetNamedValue(L"refresh_token",
                          JsonValue::CreateStringValue(winrt::hstring(tok->refreshToken)));
        obj.SetNamedValue(L"client_id", JsonValue::CreateStringValue(
                                            winrt::hstring(anthropic ? kAnthropicClientId : kOpenAiClientId)));
        body = WideToUtf8(std::wstring(obj.Stringify().c_str()));
    } catch (...) {
        *err = Tr(Str::StatusInternalError);
        return TokenEndpointResult::TransientFailure;
    }
    return PostTokenEndpoint(anthropic, L"application/json", body, tok, err, retryAfterSec);
}

