// Reusable panel surface; holds only GDI and belongs to the settings thread.
struct SettingsScrollSurface {
    HDC dc = nullptr;
    HBITMAP bitmap = nullptr;
    HGDIOBJ previous = nullptr;
    void* bits = nullptr;
    SIZE size{};
    bool contentValid = false;
    uint64_t generation = 0;

    void Reset() {
        if (dc && previous && previous != HGDI_ERROR) SelectObject(dc, previous);
        if (bitmap) DeleteObject(bitmap);
        if (dc) DeleteDC(dc);
        dc = nullptr;
        bitmap = nullptr;
        previous = nullptr;
        bits = nullptr;
        size = {};
        contentValid = false;
    }
    ~SettingsScrollSurface() { Reset(); }
    SettingsScrollSurface() = default;
    SettingsScrollSurface(const SettingsScrollSurface&) = delete;
    SettingsScrollSurface& operator=(const SettingsScrollSurface&) = delete;

    bool Ensure(HDC target, SIZE requested) {
        if (dc && size.cx == requested.cx && size.cy == requested.cy) return true;
        Reset();
        if (requested.cx <= 0 || requested.cy <= 0 ||
            uint64_t(requested.cx) * requested.cy > 16ull * 1024 * 1024) return false;
        BITMAPINFO info{};
        info.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        info.bmiHeader.biWidth = requested.cx;
        info.bmiHeader.biHeight = -requested.cy;
        info.bmiHeader.biPlanes = 1;
        info.bmiHeader.biBitCount = 32;
        info.bmiHeader.biCompression = BI_RGB;
        dc = CreateCompatibleDC(target);
        if (dc) bitmap = CreateDIBSection(target, &info, DIB_RGB_COLORS, &bits, nullptr, 0);
        if (bitmap) previous = SelectObject(dc, bitmap);
        if (!previous || previous == HGDI_ERROR) { Reset(); return false; }
        size = requested;
        return true;
    }
};

