// Navigation overlay owned and released by the settings STA; no animation callbacks.
struct SettingsIndicatorAnimation {
    struct Edges { double left = 0, top = 0, right = 0, bottom = 0; } from, to;
    bool active = false;
    bool native = false;
    bool sidebar = false;
    bool forward = false;
    int destination = -1;
    ULONGLONG start = 0;
    RECT path{};
    std::array<HWND, kSettingsPageCount> buttons{};
    winrt::Windows::UI::Composition::ShapeVisual visual{nullptr};
    winrt::Windows::UI::Composition::CompositionRoundedRectangleGeometry geometry{nullptr};
    winrt::Windows::UI::Composition::CompositionSpriteShape shape{nullptr};
    winrt::Windows::UI::Composition::CompositionColorBrush brush{nullptr};
    // The overlay's first commit can take 30-130 ms to reach DWM. Until it has, the buttons keep
    // painting the starting mark (the overlay covers it during the first leg in both directions).
    winrt::Windows::Foundation::IAsyncAction commit{nullptr};
    bool overlayShown = false;
    ULONGLONG committedAt = 0;

    void ReleaseGraphics() noexcept {
        native = false;
        overlayShown = false;
        committedAt = 0;
        commit = nullptr;
        // Restore native painting before the visual's removal reaches the compositor.
        if (active && !g_unloading) {
            for (HWND button : buttons) if (IsWindow(button))
                RedrawWindow(button, nullptr, nullptr, RDW_INVALIDATE | RDW_UPDATENOW);
        }
        try {
            if (geometry) {
                geometry.StopAnimation(L"Offset");
                geometry.StopAnimation(L"Size");
            }
            if (visual) {
                auto parent = visual.Parent();
                if (parent) parent.Children().Remove(visual);
            }
        } catch (...) {}
        try { if (visual) visual.Close(); } catch (...) {}
        try { if (shape) shape.Close(); } catch (...) {}
        try { if (geometry) geometry.Close(); } catch (...) {}
        try { if (brush) brush.Close(); } catch (...) {}
        visual = nullptr;
        shape = nullptr;
        geometry = nullptr;
        brush = nullptr;
    }
};

// Lives only in SettingsWindowState, on its STA. Installs no events or animation callbacks. Keeps
// one device per window and at most two page surfaces (each limited to 16 Mpx).
struct SettingsPageComposition {
    winrt::Windows::System::DispatcherQueueController queue{nullptr};
    HMODULE coreMessaging = nullptr;
    bool unavailable = false;
    winrt::com_ptr<ID3D11Device> d3d;
    winrt::Windows::UI::Composition::Compositor compositor{nullptr};
    winrt::Windows::UI::Composition::Desktop::DesktopWindowTarget target{nullptr};
    winrt::Windows::UI::Composition::CompositionGraphicsDevice graphics{nullptr};
    winrt::Windows::UI::Composition::CompositionDrawingSurface surface{nullptr};
    // Permanent root of the window target (created with the device). The page transition inserts
    // its tree at the bottom; other overlays (the navigation indicator) insert theirs above it.
    // Page code detaches only its own children, never the target root.
    winrt::Windows::UI::Composition::ContainerVisual base{nullptr};
    SettingsIndicatorAnimation* indicator = nullptr;  // Same STA; outlives this compositor.
    winrt::Windows::UI::Composition::ContainerVisual root{nullptr};
    winrt::Windows::UI::Composition::SpriteVisual snapshot{nullptr};
    // Commit requested when attaching; its status is polled, with no delegates.
    winrt::Windows::Foundation::IAsyncAction commit{nullptr};
    bool attached = false;
    // Previous page, retained at its displayed offset and opacity until its exit finishes.
    winrt::Windows::UI::Composition::ContainerVisual heldRoot{nullptr};
    winrt::Windows::UI::Composition::SpriteVisual held{nullptr};
    winrt::Windows::UI::Composition::CompositionDrawingSurface heldSurface{nullptr};
    RECT heldArea{};
    // Commit requested for the held page when it was attached as the incoming one (polled).
    winrt::Windows::Foundation::IAsyncAction heldCommit{nullptr};
    // The held page's fade runs as a Composition animation, independent of the UI thread.
    bool heldAnimating = false;

    // Removes a page tree from the base (no-op if it is not attached there).
    void DetachFromBase(const winrt::Windows::UI::Composition::Visual& visual) noexcept {
        try { if (base && visual && visual.Parent() == base) base.Children().Remove(visual); }
        catch (...) {}
    }
    void ClearHeld() noexcept {
        DetachFromBase(heldRoot);
        try { if (held) held.Close(); } catch (...) {}
        try { if (heldRoot) heldRoot.Close(); } catch (...) {}
        try { if (heldSurface) heldSurface.Close(); } catch (...) {}
        held = nullptr;
        heldRoot = nullptr;
        heldSurface = nullptr;
        heldCommit = nullptr;
        heldAnimating = false;
    }
    // Stop at the clock's current values, not at the entrance's final keyframe.
    void HoldSnapshot(RECT area, float offset, float opacity) noexcept {
        if (g_unloading) return;
        bool incoming = snapshot && attached;
        auto visual = incoming ? snapshot : held;
        if (!visual) return;
        try {
            visual.StopAnimation(L"Offset");
            visual.StopAnimation(L"Opacity");
            visual.Offset({0, offset, 0});
            visual.Opacity(opacity);
        } catch (...) {
            ClearSnapshot();
            return;
        }
        if (!incoming) {
            heldAnimating = false;
            return;
        }
        ClearHeld();
        held = snapshot;
        heldRoot = root;
        heldSurface = surface;
        heldArea = area;
        heldCommit = commit;
        snapshot = nullptr;
        root = nullptr;
        surface = nullptr;
        commit = nullptr;
        attached = false;
    }

    // The incoming page is still invisible; keep only the independently attached outgoing tree.
    void DropPending() noexcept {
        DetachFromBase(root);
        try { if (snapshot) snapshot.Close(); } catch (...) {}
        try { if (root) root.Close(); } catch (...) {}
        try { if (surface) surface.Close(); } catch (...) {}
        snapshot = nullptr;
        surface = nullptr;
        root = nullptr;
        commit = nullptr;
        attached = false;
    }

    void ClearSnapshot() noexcept {
        commit = nullptr;
        attached = false;
        // Detach the tree first; Close also releases the compositor's references.
        DetachFromBase(root);
        try {
            if (snapshot) {
                snapshot.StopAnimation(L"Offset");
                snapshot.StopAnimation(L"Opacity");
            }
        } catch (...) {}
        try { if (snapshot) snapshot.Close(); } catch (...) {}
        try { if (root) root.Close(); } catch (...) {}
        try { if (surface) surface.Close(); } catch (...) {}
        snapshot = nullptr;
        root = nullptr;
        surface = nullptr;
        ClearHeld();
    }
    void ReleaseGraphics() noexcept {
        if (indicator) indicator->ReleaseGraphics();
        ClearSnapshot();
        try { if (target) target.Root(nullptr); } catch (...) {}
        try { if (base) base.Close(); } catch (...) {}
        base = nullptr;
        try { if (target) target.Close(); } catch (...) {}
        try { if (graphics) graphics.Close(); } catch (...) {}
        try { if (compositor) compositor.Close(); } catch (...) {}
        target = nullptr;
        graphics = nullptr;
        compositor = nullptr;
        d3d = nullptr;
    }
    void Shutdown() noexcept {
        ReleaseGraphics();
        if (queue) {
            try {
                // The queue belongs to this thread; it is drained before leaving the STA. Completed
                // is not used (avoids a pending mod delegate during unload).
                auto done = queue.ShutdownQueueAsync();
                while (done.Status() == winrt::Windows::Foundation::AsyncStatus::Started) {
                    MsgWaitForMultipleObjectsEx(0, nullptr, 20, QS_ALLINPUT, MWMO_INPUTAVAILABLE);
                    MSG message{};
                    while (PeekMessageW(&message, nullptr, 0, 0, PM_REMOVE)) {
                        if (message.message != WM_QUIT) {
                            TranslateMessage(&message);
                            DispatchMessageW(&message);
                        }
                    }
                }
                done.GetResults();
            } catch (...) {}
            queue = nullptr;
        }
        if (coreMessaging) FreeLibrary(coreMessaging);
        coreMessaging = nullptr;
    }
    ~SettingsPageComposition() { Shutdown(); }

    bool Ensure(HWND window) {
        if (unavailable) return false;
        if (compositor) return true;
        try {
            if (!winrt::Windows::System::DispatcherQueue::GetForCurrentThread()) {
                if (!coreMessaging) coreMessaging = LoadLibraryExW(
                    L"CoreMessaging.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
                auto createQueue = coreMessaging ? reinterpret_cast<decltype(
                    &CreateDispatcherQueueController)>(GetProcAddress(
                        coreMessaging, "CreateDispatcherQueueController")) : nullptr;
                if (!createQueue) winrt::throw_hresult(E_NOTIMPL);
                DispatcherQueueOptions options{sizeof(options), DQTYPE_THREAD_CURRENT,
                                                DQTAT_COM_NONE};
                winrt::check_hresult(createQueue(options, reinterpret_cast<
                    PDISPATCHERQUEUECONTROLLER*>(winrt::put_abi(queue))));
            }
            // No WARP: if there is no accelerated device, the GDI path is good enough.
            winrt::check_hresult(D3D11CreateDevice(nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr,
                D3D11_CREATE_DEVICE_BGRA_SUPPORT, nullptr, 0, D3D11_SDK_VERSION,
                d3d.put(), nullptr, nullptr));
            winrt::com_ptr<ID2D1Factory1> factory;
            winrt::check_hresult(D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED,
                __uuidof(ID2D1Factory1), nullptr, factory.put_void()));
            winrt::com_ptr<ID2D1Device> device;
            winrt::check_hresult(factory->CreateDevice(d3d.as<IDXGIDevice>().get(), device.put()));
            compositor = winrt::Windows::UI::Composition::Compositor();
            winrt::check_hresult(compositor.as<SettingsCompositorDesktopInterop>()->
                CreateDesktopWindowTarget(window, TRUE, winrt::put_abi(target)));
            winrt::check_hresult(compositor.as<ABI::Windows::UI::Composition::ICompositorInterop>()->
                CreateGraphicsDevice(device.get(), reinterpret_cast<ABI::Windows::UI::Composition::
                    ICompositionGraphicsDevice**>(winrt::put_abi(graphics))));
            base = compositor.CreateContainerVisual();
            target.Root(base);
            Wh_Log(L"Settings page animation: native Composition initialized");
            return true;
        } catch (...) {
            Wh_Log(L"Settings page animation: Composition initialization failed (0x%08X)",
                   (unsigned)winrt::to_hresult());
            unavailable = true;
            ReleaseGraphics();
            return false;
        }
    }

    bool Prepare(HWND window, RECT area, const std::vector<uint32_t>& pixels, int distance,
                 float opacity = 0, bool hidden = false) {
        if (g_unloading || !Ensure(window)) return false;
        try {
            using namespace winrt::Windows::Graphics::DirectX;
            float width = (float)(area.right - area.left), height = (float)(area.bottom - area.top);
            surface = graphics.CreateDrawingSurface({width, height},
                DirectXPixelFormat::B8G8R8A8UIntNormalized, DirectXAlphaMode::Premultiplied);
            auto interop = surface.as<SettingsDrawingSurfaceInterop>();
            winrt::com_ptr<ID2D1DeviceContext> context;
            POINT offset{};
            winrt::check_hresult(interop->BeginDraw(nullptr, __uuidof(ID2D1DeviceContext),
                                                   context.put_void(), &offset));
            // EndDraw is mandatory even if the upload fails; a surface is never left open.
            HRESULT upload = S_OK;
            try {
                context->SetDpi(96, 96);
                context->SetTransform(D2D1::Matrix3x2F::Identity());
                D2D1_BITMAP_PROPERTIES1 props{};
                props.pixelFormat = {DXGI_FORMAT_B8G8R8A8_UNORM, D2D1_ALPHA_MODE_PREMULTIPLIED};
                props.dpiX = props.dpiY = 96;
                winrt::com_ptr<ID2D1Bitmap1> bitmap;
                winrt::check_hresult(context->CreateBitmap(
                    D2D1_SIZE_U{(UINT32)width, (UINT32)height}, pixels.data(), (UINT32)width * 4,
                    &props, bitmap.put()));
                D2D1_RECT_F bounds{(float)offset.x, (float)offset.y,
                                  offset.x + width, offset.y + height};
                context->PushAxisAlignedClip(bounds, D2D1_ANTIALIAS_MODE_ALIASED);
                context->Clear(D2D1::ColorF(0, 0.0f));
                context->DrawBitmap(bitmap.get(), bounds, 1.0f, D2D1_INTERPOLATION_MODE_LINEAR);
                context->PopAxisAlignedClip();
            } catch (...) { upload = winrt::to_hresult(); }
            HRESULT end = interop->EndDraw();
            winrt::check_hresult(upload);
            winrt::check_hresult(end);
            root = compositor.CreateContainerVisual();
            root.Opacity(hidden ? 0 : 1);
            root.Size({width, height});
            root.Offset({(float)area.left, (float)area.top, 0});
            root.Clip(compositor.CreateInsetClip());
            snapshot = compositor.CreateSpriteVisual();
            snapshot.Size({width, height});
            snapshot.Offset({0, (float)distance, 0});
            snapshot.Opacity(opacity);
            auto brush = compositor.CreateSurfaceBrush(surface);
            brush.Stretch(winrt::Windows::UI::Composition::CompositionStretch::None);
            snapshot.Brush(brush);
            root.Children().InsertAtTop(snapshot);
            // Each page has its own clipped tree so the outgoing surface can be released early.
            return true;
        } catch (...) {
            Wh_Log(L"Settings page animation: snapshot upload failed (0x%08X)",
                   (unsigned)winrt::to_hresult());
            unavailable = true;
            ReleaseGraphics();
            return false;
        }
    }

    // The incoming page attaches invisibly during the exit; poll its upload before starting it.
    bool Attach() {
        if (g_unloading) return false;
        try {
            base.Children().InsertAtBottom(root);
            attached = true;
            // RequestCommitAsync (Windows 10 1903+): if it does not exist, the maximum time is
            // waited.
            try { commit = compositor.RequestCommitAsync(); } catch (...) { commit = nullptr; }
            return true;
        } catch (...) {
            Wh_Log(L"Settings page animation: Composition attach failed (0x%08X)",
                   (unsigned)winrt::to_hresult());
            unavailable = true;
            ReleaseGraphics();
            return false;
        }
    }
    bool Committed() noexcept {
        try {
            return commit && commit.Status() != winrt::Windows::Foundation::AsyncStatus::Started;
        } catch (...) { return true; }
    }
    bool HeldCommitted() noexcept {
        try {
            return heldCommit &&
                   heldCommit.Status() != winrt::Windows::Foundation::AsyncStatus::Started;
        } catch (...) { return true; }
    }

    // Exit frames follow the shared clock. Until the surface commits, its root stays hidden and
    // the native DIB presents the same fade, avoiding a gap or two translucent copies at upload.
    bool PresentExit(float offset, float opacity, bool visible) {
        if (g_unloading) return false;
        try {
            if (!held) return false;
            if (!heldAnimating) {
                held.StopAnimation(L"Offset");
                held.StopAnimation(L"Opacity");
                held.Offset({0, offset, 0});
                held.Opacity(opacity);
            }
            if (heldRoot) heldRoot.Opacity(visible ? 1 : 0);
            return true;
        } catch (...) {
            unavailable = true;
            ReleaseGraphics();
            return false;
        }
    }

    // Shows the held page and fades it through `opacities` (evenly spaced keyframes of the exit
    // curve) in `durationMs`, so the exit keeps running while the UI thread lays out the next page.
    bool AnimateExit(float offset, const std::array<float, 9>& opacities, ULONGLONG durationMs) {
        if (g_unloading) return false;
        try {
            if (!held) return false;
            held.StopAnimation(L"Offset");
            held.StopAnimation(L"Opacity");
            held.Offset({0, offset, 0});
            held.Opacity(opacities[0]);
            auto linear = compositor.CreateLinearEasingFunction();
            auto fade = compositor.CreateScalarKeyFrameAnimation();
            for (size_t i = 0; i < opacities.size(); i++) {
                fade.InsertKeyFrame(float(i) / float(opacities.size() - 1), opacities[i], linear);
            }
            fade.Duration(std::chrono::milliseconds(std::max<ULONGLONG>(durationMs, 1)));
            held.StartAnimation(L"Opacity", fade);
            if (heldRoot) heldRoot.Opacity(1);
            heldAnimating = true;
            // Polled before the UI thread blocks: Composition commits only from the message loop.
            try { heldCommit = compositor.RequestCommitAsync(); } catch (...) { heldCommit = nullptr; }
            return true;
        } catch (...) {
            unavailable = true;
            ReleaseGraphics();
            return false;
        }
    }

    bool Start(int distance) {
        if (g_unloading) return false;
        try {
            const auto& curve = kSettingsPageEnterCurve;
            auto easing = compositor.CreateCubicBezierEasingFunction(
                {curve.x1, curve.y1}, {curve.x2, curve.y2});
            auto move = compositor.CreateVector3KeyFrameAnimation();
            move.InsertKeyFrame(0, {0, (float)distance, 0});
            move.InsertKeyFrame(1, {0, 0, 0}, easing);
            move.Duration(std::chrono::milliseconds(kSettingsPageEnterMs));
            auto fade = compositor.CreateScalarKeyFrameAnimation();
            fade.InsertKeyFrame(0, 0);
            fade.InsertKeyFrame(1, 1, compositor.CreateLinearEasingFunction());
            fade.Duration(std::chrono::milliseconds(kSettingsPageFadeMs));
            snapshot.StartAnimation(L"Offset", move);
            snapshot.StartAnimation(L"Opacity", fade);
            ClearHeld();
            if (!attached) {
                base.Children().InsertAtBottom(root);
                attached = true;
            }
            return true;
        } catch (...) {
            Wh_Log(L"Settings page animation: Composition start failed (0x%08X)",
                   (unsigned)winrt::to_hresult());
            unavailable = true;
            ReleaseGraphics();
            return false;
        }
    }
};

static constexpr UINT_PTR kSettingsWheelTimer = 0x57484545;
static constexpr UINT_PTR kSettingsExpanderTimer = 0x45585041;
