struct SettingsWindowState {
    std::vector<uint32_t> appLogo;  // About header logo (BGRA master).
    HWND hWnd = nullptr;
    std::array<HWND, kSettingsPageCount> pageButtons{};
    HWND viewport = nullptr;
    HWND scrollBar = nullptr;
    HWND pageHeading = nullptr;
    HWND infoBarMessage = nullptr;
    HWND infoBarClose = nullptr;
    bool infoBarVisible = false;
    InfoBarSeverity infoBarSeverity = InfoBarSeverity::Info;
    std::wstring infoBarText;
    RECT infoBarRect{};
    HWND accountList = nullptr;
    HWND toolTip = nullptr;
    HWND colorDialog = nullptr;
    int closeAttempts = 0;  // Paced WM_CLOSE retries while a modal dialog is open.
    std::array<std::vector<HWND>, kSettingsPageCount> pageControls;
    std::array<std::vector<SettingsRow>, kSettingsPageCount> rows;
    NativeTheme theme;
    NativeBackdrop backdrop;
    RECT listCard{};
    // Navigation geometry (LayoutSettingsWindow): side pane or horizontal selector.
    RECT navigationRect{};
    RECT contentRect{};
    RECT pageHeadingRect{};
    bool sidebarNavigation = false;
    int currentPage = 0;
    RECT viewportRect{};
    std::array<int, kSettingsPageCount> scrollOffsets{};
    int scrollExtent = 0;
    // Height of the cards without the bottom margin. If it fits in the panel, the margin cannot be
    // scrolled: this way no scrollbar appears just to move the empty margin.
    int scrollContentExtent = 0;
    double wheelRemainder = 0;
    bool wheelActive = false;
    int wheelTarget = 0;
    int wheelStartOffset = 0;
    ULONGLONG wheelStart = 0;
    SettingsScrollSurface scrollSurface;
    // Fluent scrollbar (SettingsScrollBarSubclassProc): a thin indicator that widens with the
    // pointer; dragging, page/line repeat and touch panning.
    bool scrollHot = false;
    int scrollPart = 0;          // ScrollPart active while pressed (0: none).
    int scrollDragAnchor = 0;    // Distance from the pointer to the start of the thumb while dragging.
    int panLastY = 0;            // Last touch panning point (screen).
    // Accessibility > Visual effects > Always show scrollbars.
    bool scrollAlwaysExpanded = false;
    UINT dpi = 96;
    bool updating = false;
    bool inSizeMove = false;
    bool changeQueued = false;  // A kSettingsDeferredChangeMessage is posted and not yet handled.
    bool visualsQueued = false;
    bool fitQueued = false;
    int activationRepaints = 0;  // Pending passes of kSettingsActivationRepaintTimer.
    bool zoomed = false;         // Last maximized state seen in WM_SIZE.
    SIZE layoutSize{};           // Client area of the last LayoutSettingsWindow.
    bool viewportPaintHeld = false;  // Navigation click: panel suspended (WM_SETREDRAW).
    bool viewportWanted = false;     // Visibility the layout wanted for the panel.
    std::vector<HWND> deferredShow;  // Children of the root shown when the click finishes.
    std::array<COLORREF, 16> customColors{};
    SettingsIndicatorAnimation indicatorAnimation;
    // Clipped page captures fade out, then slide and fade in. Native controls remain suspended
    // until the final snapshot is handed back to the HWND tree.
    struct PageAnimation {
        bool active = false;
        ULONGLONG start = 0;          // Outgoing fade's clock, if there is a previous page.
        ULONGLONG enterStart = 0;     // Starts after both exit and incoming commit are ready.
        bool pendingExit = false;
        bool exitComposed = false;    // Outgoing surface uploaded; native DC contains background.
        float exitOffset = 0;
        float exitOpacity = 1;
        RECT area{};                  // Client area of the root.
        int distance = 0;
        uint32_t background = 0;      // Premultiplied background pixel (0 over the material).
        bool outputBackground = false;
        std::vector<uint32_t> content;
        std::vector<uint32_t> previous;
        std::vector<HWND> frozen;
        SettingsScrollSurface output; // Independent of the scroll cache.
        SettingsPageComposition composition;
        bool native = false;
        ULONGLONG attachedAt = 0;     // Composition: snapshot attached, waiting for DWM.
        // Exit phase of a navigation: the destination page, whose work (visibility, layout and
        // capture) waits until the exit runs in Composition or ends. -1 otherwise.
        int deferredPage = -1;
    } pageAnimation;
    // Local transition: one clipped capture, without moving HWNDs every frame.
    struct ExpanderAnimation {
        bool active = false;
        bool expanding = false;
        int parentId = 0;
        int page = 0;
        RECT area{};
        ULONGLONG start = 0;
        std::vector<uint32_t> content;
        std::vector<HWND> frozen;
        SettingsScrollSurface output;
        bool finished = false;  // Finished its curve (timer), not cut short by another change.
        HWND focusAfter = nullptr;
        HWND focusBefore = nullptr;
    } expanderAnimation;
    int expanderHot = 0;      // Parent whose header is under the pointer (0: none).
    int expanderPressed = 0;  // Parent whose header is being pressed.
    ULONGLONG chevronStart = 0;
    bool chevronExpanded = false;
    int chevronParent = 0;    // Expander whose chevron is rotating.
    // Reordering the account list by dragging a row (AccountListSubclassProc), as WinUI's
    // ListView does: the row lifts into a shadowed copy that follows the pointer and the other
    // rows slide apart to open a gap where it will land.
    struct AccountDrag {
        bool active = false;
        int source = -1;           // Row being dragged.
        uint64_t identity = 0;     // Its account, to survive a list refresh.
        int target = -1;           // Row it would take if dropped now (the gap).
        std::vector<float> offsets;  // Painted minus real top of each row, in pixels.
        int grabY = 0;             // Pointer to the top of the row, in pixels.
        int scrollDirection = 0;   // Auto-scroll near the edges: -1 up, 1 down, 0 off.
        HWND ghost = nullptr;      // Layered copy of the row.
        int ghostMargin = 0;       // Shadow margin around the row inside the ghost.
        int ghostLeft = 0;         // Left edge of the lifted row (list client coordinates).
        int rowHeight = 0;
    } accountDrag;
};

