// Native menus of this thread only; another app's #32768 must never be touched.
HWND FindOwnMenuWindow() {
    HWND w = nullptr;
    while ((w = FindWindowExW(nullptr, w, L"#32768", nullptr)) != nullptr)
        if (GetWindowThreadProcessId(w, nullptr) == GetCurrentThreadId()) return w;
    return nullptr;
}

// Shows the Seamless Taskbar menu. The picker thread is DPI-unaware, the menu is
// per-monitor aware, so a logical point is converted first.
int RunSeamlessMenu(HWND owner, const std::vector<::stset::SetMenuItem>& items, const POINT* logical) {
    POINT at{};
    if (logical) {
        at = *logical;
        if (g_pickerWindow) LogicalToPhysicalPointForPerMonitorDPI(g_pickerWindow, &at);
    }
    DPI_AWARENESS_CONTEXT old = SetThreadDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);
    g_seamlessMenuOpen = true;
    const int cmd = ::stset::Set_TrayMenu(owner, items, logical ? &at : nullptr);
    g_seamlessMenuOpen = false;
    if (old) SetThreadDpiAwarenessContext(old);
    return cmd;
}
